import{_ as n,y as u,a as l,o as i,a2 as o,D as a,g as t,I as r}from"./chunks/framework.DCcmcJcL.js";const C=JSON.parse('{"title":"Customer Groups","description":"","frontmatter":{},"headers":[],"relativePath":"customer/customer-group.md","filePath":"customer/customer-group.md","lastUpdated":1789441803000}'),g={name:"customer/customer-group.md"};function p(h,e,d,c,m,f){const s=u("ImagePopup");return i(),l("div",null,[e[3]||(e[3]=o('<h1 id="customer-groups" tabindex="-1">Customer Groups <a class="header-anchor" href="#customer-groups" aria-label="Permalink to &quot;Customer Groups&quot;">​</a></h1><p>A customer group sorts your customers so you can price and promote to them differently, for example to give trade customers lower prices. Every customer belongs to one group, and shoppers who aren&#39;t signed in are treated as the <strong>Guest</strong> group.</p><h2 id="what-groups-are-used-for" tabindex="-1">What groups are used for <a class="header-anchor" href="#what-groups-are-used-for" aria-label="Permalink to &quot;What groups are used for&quot;">​</a></h2><ul><li><strong>Customer group prices:</strong> lower prices on a product for a group, for larger quantities, or both. See <a href="./customer-group-price.html">Customer Group Pricing</a>.</li><li><strong>Cart rules:</strong> a cart rule&#39;s discount applies only to the <strong>Customer Groups</strong> you tick on the rule. See <a href="./../marketing/cart-rules.html">Cart Rules</a>.</li><li><strong>Catalog rules:</strong> a catalog rule&#39;s discounted price applies only to the <strong>Customer Groups</strong> you choose on the rule. See <a href="./../marketing/catalog-rules.html">Catalog Rules</a>.</li></ul><h2 id="the-default-groups" tabindex="-1">The default groups <a class="header-anchor" href="#the-default-groups" aria-label="Permalink to &quot;The default groups&quot;">​</a></h2><p>Bagisto comes with three groups:</p><table tabindex="0"><thead><tr><th>Group</th><th>Code</th><th>Who&#39;s in it</th></tr></thead><tbody><tr><td><strong>Guest</strong></td><td><code>guest</code></td><td>Shoppers who aren&#39;t signed in. You can&#39;t choose it for a customer in the admin panel.</td></tr><tr><td><strong>General</strong></td><td><code>general</code></td><td>Customers who sign up on the storefront, unless you choose another group for new accounts.</td></tr><tr><td><strong>Wholesale</strong></td><td><code>wholesale</code></td><td>Nobody, until you move customers into it, for example your trade customers.</td></tr></tbody></table><p>You can rename the default groups, but you can&#39;t delete them.</p><div class="warning custom-block"><p class="custom-block-title">Keep the codes of the default groups</p><p>The storefront finds the group for new accounts by its code. Change a default group&#39;s <strong>Name</strong> if you like, but leave its <strong>Code</strong> as it is.</p></div><h2 id="the-groups-list" tabindex="-1">The groups list <a class="header-anchor" href="#the-groups-list" aria-label="Permalink to &quot;The groups list&quot;">​</a></h2><p>Go to <strong>Customers &gt;&gt; Groups</strong>.</p>',11)),a(s,{src:"/images/customer/group-grid.png",alt:"The groups list under Customers >> Groups with the Wholesale, General and Guest groups"}),e[4]||(e[4]=o('<p>The list shows each group&#39;s <strong>ID</strong>, <strong>Code</strong> and <strong>Name</strong>.</p><ul><li><strong>Search:</strong> type in the search box to find groups by name.</li><li><strong>Filter:</strong> click <strong>Filter</strong> and filter by <strong>ID</strong>, <strong>Code</strong> or <strong>Name</strong>.</li><li><strong>Sort:</strong> click <strong>ID</strong>, <strong>Code</strong> or <strong>Name</strong> in the header row.</li><li><strong>Edit</strong> (the pencil) and <strong>Delete</strong> (the bin) are at the end of each row.</li></ul><h2 id="create-a-group" tabindex="-1">Create a group <a class="header-anchor" href="#create-a-group" aria-label="Permalink to &quot;Create a group&quot;">​</a></h2>',3)),t("ol",null,[e[1]||(e[1]=o("<li><p>Go to <strong>Customers &gt;&gt; Groups</strong>.</p></li><li><p>Click <strong>Create Group</strong>. The <strong>Create new Group</strong> dialog opens.</p></li><li><p>Enter the <strong>Code</strong>, a unique identifier such as <code>retail_club</code>. It must start with a letter and can contain letters, numbers and underscores.</p></li>",3)),t("li",null,[e[0]||(e[0]=t("p",null,[r("Enter the "),t("strong",null,"Name"),r(", which the admin panel shows wherever you choose a group.")],-1)),a(s,{src:"/images/customer/create-group.png",alt:"Create new Group dialog with the code retail_club and the name Retail Club"})]),e[2]||(e[2]=t("li",null,[t("p",null,[r("Click "),t("strong",null,"Save Group"),r(". The group is added to the list.")])],-1))]),e[5]||(e[5]=o('<h2 id="edit-a-group" tabindex="-1">Edit a group <a class="header-anchor" href="#edit-a-group" aria-label="Permalink to &quot;Edit a group&quot;">​</a></h2><ol><li>Go to <strong>Customers &gt;&gt; Groups</strong>.</li><li>Click the pencil on the group&#39;s row. The <strong>Edit Group</strong> dialog opens.</li><li>Change the <strong>Code</strong> or <strong>Name</strong>.</li><li>Click <strong>Save Group</strong>.</li></ol><h2 id="delete-a-group" tabindex="-1">Delete a group <a class="header-anchor" href="#delete-a-group" aria-label="Permalink to &quot;Delete a group&quot;">​</a></h2><ol><li>Go to <strong>Customers &gt;&gt; Groups</strong>.</li><li>Click the bin on the group&#39;s row.</li><li>Click <strong>Agree</strong> to confirm.</li></ol><p>A group can&#39;t be deleted when:</p><ul><li>it&#39;s one of the default groups. The page shows <em>Default Group Can not be Deleted</em>.</li><li>customers still belong to it. The page shows <em>This group has associated customers and cannot be deleted.</em> Move the customers to another group first, with <strong>Edit</strong> on each customer&#39;s page. See <a href="./create-customer.html#edit-customer-details">Edit customer details</a>.</li></ul><h2 id="the-group-for-new-customers" tabindex="-1">The group for new customers <a class="header-anchor" href="#the-group-for-new-customers" aria-label="Permalink to &quot;The group for new customers&quot;">​</a></h2><p>Customers who sign up on the storefront join the <strong>Default Group</strong> chosen in <a href="./../configure/settings.html#create-new-account-options">Customer Settings</a>, which is <strong>General</strong> in a new store. When you create a customer in the admin panel, you choose their group in the dialog. You can move a customer to another group at any time with <strong>Edit</strong> on their page.</p>',8))])}const b=n(g,[["render",p]]);export{C as __pageData,b as default};
